const entrada = $input.first().json ?? {};

const entidades = {
  leads_unificados: {
    tabela: 'analise_dados.vw_leads_com_dados_unificados',
    campos: [
      'id', 'id_externo', 'nome', 'venda', 'contato_id_externo',
      'contato_nome', 'contato_telefone', 'contato_email', 'contato_cargo',
      'empresa_id_externo', 'empresa_nome', 'empresa_telefone',
      'empresa_email', 'empresa_ltv', 'funil_id_externo', 'funil_nome',
      'etapa_id_externo', 'etapa_nome', 'etapa_ordem',
      'usuario_responsavel_id_externo', 'usuario_responsavel_nome',
      'usuario_responsavel_papel', 'utm_source', 'utm_campaing',
      'utm_medium', 'utm_content', 'servicos', 'data_contrato',
      'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id_externo', 'nome', 'venda', 'contato_nome', 'empresa_nome',
      'funil_nome', 'etapa_nome', 'usuario_responsavel_nome',
      'servicos', 'data_contrato', 'criado_em'
    ],
    numericos: ['id', 'venda', 'empresa_ltv', 'etapa_ordem']
  },
  leads: {
    tabela: 'analise_dados.leads',
    campos: [
      'id', 'id_externo', 'contato_id_externo', 'empresa_id_externo',
      'etapa_id_externo', 'funil_id_externo',
      'usuario_responsavel_id_externo', 'nome', 'venda', 'utm_source',
      'utm_campaing', 'utm_medium', 'utm_content', 'servicos',
      'data_contrato', 'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id_externo', 'nome', 'venda', 'etapa_id_externo',
      'funil_id_externo', 'usuario_responsavel_id_externo',
      'servicos', 'data_contrato', 'criado_em'
    ],
    numericos: ['id', 'venda']
  },
  contatos: {
    tabela: 'analise_dados.contatos',
    campos: [
      'id', 'id_externo', 'empresa_id', 'empresa_id_externo', 'nome',
      'telefone', 'email', 'cargo', 'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id_externo', 'empresa_id_externo', 'nome', 'telefone', 'email',
      'cargo', 'criado_em'
    ],
    numericos: ['id', 'empresa_id']
  },
  empresas: {
    tabela: 'analise_dados.empresas',
    campos: [
      'id', 'id_externo', 'nome', 'telefone', 'email', 'ltv',
      'data_ultimo_contrato', 'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id_externo', 'nome', 'telefone', 'email', 'ltv',
      'data_ultimo_contrato', 'criado_em'
    ],
    numericos: ['id', 'ltv']
  },
  usuarios: {
    tabela: 'analise_dados.usuarios',
    campos: [
      'id', 'id_externo', 'nome', 'papel', 'criado_em', 'atualizado_em'
    ],
    padrao: ['id_externo', 'nome', 'papel', 'criado_em'],
    numericos: ['id']
  },
  funis: {
    tabela: 'analise_dados.funis',
    campos: ['id', 'id_externo', 'nome', 'criado_em', 'atualizado_em'],
    padrao: ['id_externo', 'nome', 'criado_em'],
    numericos: ['id']
  },
  etapas: {
    tabela: 'analise_dados.etapas',
    campos: [
      'id', 'id_externo', 'funil_id', 'funil_id_externo', 'nome',
      'descricao', 'ordem', 'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id_externo', 'funil_id_externo', 'nome', 'descricao', 'ordem'
    ],
    numericos: ['id', 'funil_id', 'ordem']
  },
  insights: {
    tabela: 'analise_dados.insights',
    campos: [
      'id', 'titulo_da_analise', 'oque_foi_analisado', 'resultado',
      'recomendado', 'criado_em', 'atualizado_em'
    ],
    padrao: [
      'id', 'titulo_da_analise', 'resultado', 'recomendado', 'criado_em'
    ],
    numericos: ['id']
  }
};

const parseJsonRecursivo = (valor, nome, profundidade = 0) => {
  if (profundidade > 3 || typeof valor !== 'string') return valor;

  const texto = valor.trim();
  if (!texto) return texto;

  try {
    return parseJsonRecursivo(JSON.parse(texto), nome, profundidade + 1);
  } catch {
    if (profundidade === 0) {
      throw new Error(`${nome} deve conter JSON valido.`);
    }
    return valor;
  }
};

const parseArray = (valor, nome) => {
  if (valor === undefined || valor === null || valor === '') return [];

  const parsed = parseJsonRecursivo(valor, nome);
  if (!Array.isArray(parsed)) {
    throw new Error(`${nome} deve ser um array JSON.`);
  }

  return parsed.map((item, indice) => {
    if (typeof item !== 'string') return item;

    try {
      return parseJsonRecursivo(item, `${nome}[${indice}]`);
    } catch {
      return item;
    }
  });
};

const literalSql = (valor) => {
  if (valor === null || valor === undefined) return 'NULL';
  if (typeof valor === 'boolean') return valor ? 'TRUE' : 'FALSE';

  if (typeof valor === 'number') {
    if (!Number.isFinite(valor)) throw new Error('Valor numerico invalido.');
    return String(valor);
  }

  if (typeof valor !== 'string') {
    throw new Error('Filtros aceitam somente texto, numero, booleano ou null.');
  }

  return `'${valor.replace(/'/g, "''")}'`;
};

const validarValorFiltro = (valor) => {
  const valores = Array.isArray(valor) ? valor : [valor];
  for (const item of valores) {
    if (typeof item === 'string' && item.length > 500) {
      throw new Error('Valor de filtro excede 500 caracteres.');
    }
  }
};

const validarCampo = (config, campo) => {
  if (typeof campo !== 'string' || !config.campos.includes(campo)) {
    throw new Error(`Campo nao permitido: ${String(campo)}.`);
  }
  return campo;
};

// Aceita campo como string ("etapa_nome") ou objeto ({ campo: "etapa_nome" }).
const extrairNomeCampo = (campo) => {
  if (campo && typeof campo === 'object' && !Array.isArray(campo)) {
    return campo.campo ?? campo.field ?? campo.nome ?? campo.name ?? campo.coluna;
  }
  return campo;
};

const catalogo = Object.fromEntries(
  Object.entries(entidades).map(([nome, config]) => [nome, {
    campos: config.campos,
    campos_numericos: config.numericos
  }])
);

const operacao = String(entrada.operacao || 'listar').trim().toLowerCase();

if (operacao === 'catalogo') {
  return [{
    json: {
      query: `SELECT ${literalSql(JSON.stringify(catalogo))}::jsonb AS catalogo`,
      contexto: { operacao: 'catalogo', entidade: null, limite: 1 }
    }
  }];
}

if (!['listar', 'agregar'].includes(operacao)) {
  throw new Error('operacao deve ser catalogo, listar ou agregar.');
}

const entidade = String(entrada.entidade || '').trim().toLowerCase();
const config = entidades[entidade];

if (!config) {
  throw new Error(`Entidade nao permitida: ${entidade || '(vazia)'}. Use a operacao catalogo.`);
}

const filtros = parseArray(entrada.filtros, 'filtros');
if (filtros.length > 12) throw new Error('No maximo 12 filtros sao permitidos.');

const aliasesOperadores = {
  '=': 'igual',
  '==': 'igual',
  'eq': 'igual',
  '!=': 'diferente',
  '<>': 'diferente',
  'ne': 'diferente',
  '>': 'maior',
  'gt': 'maior',
  '>=': 'maior_ou_igual',
  'gte': 'maior_ou_igual',
  '<': 'menor',
  'lt': 'menor',
  '<=': 'menor_ou_igual',
  'lte': 'menor_ou_igual',
  'contains': 'contem',
  'in': 'em',
  'between': 'entre',
  'is_null': 'nulo',
  'not_null': 'nao_nulo'
};

const operadores = {
  igual: '=',
  diferente: '<>',
  maior: '>',
  maior_ou_igual: '>=',
  menor: '<',
  menor_ou_igual: '<='
};

const where = filtros.map((filtro) => {
  if (!filtro || typeof filtro !== 'object' || Array.isArray(filtro)) {
    throw new Error('Cada filtro deve ser um objeto JSON.');
  }

  const campo = validarCampo(config, filtro.campo);
  const operadorRecebido = String(filtro.operador || 'igual').trim().toLowerCase();
  const operador = aliasesOperadores[operadorRecebido] || operadorRecebido;
  validarValorFiltro(filtro.valor);

  if (operadores[operador]) {
    if (filtro.valor === null || filtro.valor === undefined) {
      return `${campo} IS ${operador === 'diferente' ? 'NOT ' : ''}NULL`;
    }
    return `${campo} ${operadores[operador]} ${literalSql(filtro.valor)}`;
  }

  if (operador === 'contem') {
    if (typeof filtro.valor !== 'string') {
      throw new Error(`O operador contem exige texto no campo ${campo}.`);
    }
    return `${campo}::text ILIKE ${literalSql(`%${filtro.valor}%`)}`;
  }

  if (operador === 'em') {
    if (!Array.isArray(filtro.valor) || filtro.valor.length === 0) {
      throw new Error(`O operador em exige uma lista nao vazia no campo ${campo}.`);
    }
    if (filtro.valor.length > 100) {
      throw new Error(`O filtro em aceita no maximo 100 valores no campo ${campo}.`);
    }
    return `${campo} IN (${filtro.valor.map(literalSql).join(', ')})`;
  }

  if (operador === 'entre') {
    if (!Array.isArray(filtro.valor) || filtro.valor.length !== 2) {
      throw new Error(`O operador entre exige exatamente dois valores no campo ${campo}.`);
    }
    return `${campo} BETWEEN ${literalSql(filtro.valor[0])} AND ${literalSql(filtro.valor[1])}`;
  }

  if (operador === 'nulo') return `${campo} IS NULL`;
  if (operador === 'nao_nulo') return `${campo} IS NOT NULL`;

  throw new Error(`Operador nao permitido: ${operador}.`);
});

const limiteSolicitado = Number(entrada.limite || 50);
const limite = Number.isInteger(limiteSolicitado)
  ? Math.min(Math.max(limiteSolicitado, 1), 200)
  : 50;

const agruparPor = parseArray(entrada.agrupar_por, 'agrupar_por')
  .map((campo) => validarCampo(config, extrairNomeCampo(campo)));

let camposSelecionados;
let aliasesMetricas = [];

if (operacao === 'listar') {
  const solicitados = parseArray(entrada.campos, 'campos');
  camposSelecionados = (solicitados.length ? solicitados : config.padrao)
    .map((campo) => validarCampo(config, extrairNomeCampo(campo)));

  if (camposSelecionados.length > 30) {
    throw new Error('No maximo 30 campos podem ser retornados.');
  }
} else {
  const metricasRecebidas = parseArray(entrada.metricas, 'metricas');
  const metricas = metricasRecebidas.length
    ? metricasRecebidas
    : [{ funcao: 'contar', campo: '*', alias: 'total' }];

  if (metricas.length > 10) throw new Error('No maximo 10 metricas sao permitidas.');

  const expressoes = metricas.map((metrica, indice) => {
    if (!metrica || typeof metrica !== 'object' || Array.isArray(metrica)) {
      throw new Error('Cada metrica deve ser um objeto JSON.');
    }

    const aliasesFuncoes = {
      count: 'contar',
      sum: 'somar',
      avg: 'media',
      average: 'media',
      min: 'minimo',
      max: 'maximo'
    };
    let funcaoRecebida = String(
      metrica.funcao || metrica.operacao || metrica.agregacao || metrica.agg || ''
    ).trim().toLowerCase();
    let campoRecebido = metrica.campo;

    if (metrica.expressao !== undefined && metrica.expressao !== null) {
      const expressao = String(metrica.expressao).trim().toLowerCase();
      const correspondencia = expressao.match(
        /^(count|sum|avg|average|min|max)\(([a-z_][a-z0-9_]*|\*)\)$/
      );

      if (!correspondencia) {
        throw new Error(
          `Expressao de metrica nao permitida: ${expressao}. Use o formato count(campo), sum(campo), avg(campo), min(campo) ou max(campo).`
        );
      }

      [, funcaoRecebida, campoRecebido] = correspondencia;
    }

    const funcao = aliasesFuncoes[funcaoRecebida] || funcaoRecebida;
    const funcoes = {
      contar: 'COUNT',
      somar: 'SUM',
      media: 'AVG',
      minimo: 'MIN',
      maximo: 'MAX'
    };

    if (!funcoes[funcao]) throw new Error(`Funcao de metrica nao permitida: ${funcao}.`);

    const campo = campoRecebido === '*' ? '*' : validarCampo(config, campoRecebido);
    if (funcao !== 'contar' && !config.numericos.includes(campo)) {
      throw new Error(`A metrica ${funcao} exige campo numerico: ${campo}.`);
    }

    const aliasPadrao = `${funcao}_${campo === '*' ? 'registros' : campo}`;
    const alias = String(metrica.alias || aliasPadrao);
    if (!/^[a-z][a-z0-9_]{0,39}$/i.test(alias)) {
      throw new Error(`Alias de metrica invalido: ${alias}.`);
    }

    aliasesMetricas.push(alias);
    const argumento = campo === '*' ? '*' : campo;
    return `${funcoes[funcao]}(${argumento}) AS ${alias}`;
  });

  camposSelecionados = [...agruparPor, ...expressoes];
}

const ordenacao = parseArray(entrada.ordenacao, 'ordenacao');
if (ordenacao.length > 5) throw new Error('No maximo 5 ordenacoes sao permitidas.');

const camposOrdenaveis = operacao === 'listar'
  ? new Set(camposSelecionados)
  : new Set([...agruparPor, ...aliasesMetricas]);

const orderBy = ordenacao.map((item) => {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    throw new Error('Cada ordenacao deve ser um objeto JSON.');
  }

  const campo = String(item.campo || '');
  if (!camposOrdenaveis.has(campo)) {
    throw new Error(`Campo nao disponivel para ordenacao: ${campo}.`);
  }

  const direcao = String(item.direcao || 'asc').toLowerCase();
  if (!['asc', 'desc'].includes(direcao)) {
    throw new Error(`Direcao de ordenacao invalida: ${direcao}.`);
  }

  return `${campo} ${direcao.toUpperCase()}`;
});

let query = `SELECT ${camposSelecionados.join(', ')} FROM ${config.tabela}`;
if (where.length) query += ` WHERE ${where.join(' AND ')}`;
if (operacao === 'agregar' && agruparPor.length) {
  query += ` GROUP BY ${agruparPor.join(', ')}`;
}
if (orderBy.length) query += ` ORDER BY ${orderBy.join(', ')}`;
query += ` LIMIT ${limite}`;

return [{
  json: {
    query,
    contexto: {
      operacao,
      entidade,
      limite,
      filtros_aplicados: filtros.length
    }
  }
}];

const contexto = $('Construir consulta segura').first().json.contexto;
const linhas = $input.all()
  .map((item) => item.json)
  .filter((linha) => Object.keys(linha).length > 0);

return [{
  json: {
    sucesso: true,
    contexto,
    total_retornado: linhas.length,
    dados: linhas
  }
}];
